"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["48531"],{82015(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.requisicao.corpo_acima_do_limite","status":413,"titulo":"O corpo da requisi\xe7\xe3o passa do tamanho aceito"},"descricao":{"codigo":"uniplus.requisicao.corpo_acima_do_limite","requisitos":[],"oQueAconteceu":["O corpo da requisi\xe7\xe3o passa do tamanho que a opera\xe7\xe3o aceita. Com o tamanho declarado acima do limite, a recusa vem antes de verificar o acesso e de ler o conte\xfado. Sem tamanho declarado, com o conte\xfado enviado em partes, a leitura \xe9 interrompida ao passar do limite, e a verifica\xe7\xe3o de acesso pode recusar antes disso.","Cada opera\xe7\xe3o tem um limite: o geral da API, igual para as opera\xe7\xf5es que recebem JSON, ou o pr\xf3prio da opera\xe7\xe3o, como o do envio do arquivo de retorno do INEP. O campo `detail` da resposta informa o limite em vigor, em bytes.","A recusa vale tanto quando o tamanho \xe9 declarado no cabe\xe7alho da requisi\xe7\xe3o quanto quando o corpo chega em partes, sem tamanho declarado: neste caso a leitura \xe9 interrompida ao passar do limite.","A resposta n\xe3o repete nenhum trecho do corpo recebido nem o tamanho declarado."],"comoResolver":["Reduza o conte\xfado enviado para caber no limite informado em `detail` e envie de novo.","Se o corpo cabe no limite e a recusa continua, confira se o cliente n\xe3o est\xe1 enviando o conte\xfado mais de uma vez nem acrescentando dados que a opera\xe7\xe3o n\xe3o pede."],"ondeAparece":["Qualquer opera\xe7\xe3o que recebe corpo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Requisicao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);